export type ApiError = {
    code: string;
    fields: Array<string>;
    message: string;
    requestId: string;
};

/**
 * Unified API error envelope (design §13.3): clients depend only on `code`;
 * `message` never leaks SQL, RPC URLs, credentials, or stacks; `requestId`
 * correlates a response with its request log; `fields` carries per-field
 * validation details when a later ticket adds them.
 */
export type ApiErrorBody = {
    error: ApiError;
};

/**
 * One recorded provider attempt (redacted provider result).
 */
export type AttemptRow = {
    attemptId: string;
    attemptNumber: number;
    attemptedAt: string;
    deliveryId: string;
    durationMs?: number | null;
    errorKind?: string | null;
    outcome: string;
    providerResult: string;
    retryAfterSeconds?: number | null;
};

/**
 * One Item reference the Owner echoed back. The boundary is opaque to the
 * browser; the Server only needs to match it against the current evidence.
 */
export type AttentionAcknowledgment = {
    evidence_key: string;
    kind: AttentionKind;
};

/**
 * One Server-owned Attention Item (design §8.4.2, §15.6).
 */
export type AttentionItem = {
    /**
     * Server-owned occurrence/evidence boundary. An Owner acknowledgment
     * echoes this value back and applies only while it is still current, so
     * new evidence is never swallowed by a stale confirmation. The WebUI
     * treats it as opaque.
     */
    evidence_key: string;
    /**
     * Stable item key (kind + subject) for list rendering and tests.
     */
    id: string;
    kind: AttentionKind;
    message: string;
    /**
     * Last authoritative observation time for this item. None means the
     * Server has no observation timestamp for the evidence; it is never
     * replaced with the snapshot generation time, which is not an event or
     * observation time.
     */
    observed_at: string | null;
    severity: AttentionSeverity;
    subject_id: string;
    subject_kind: AttentionSubjectKind;
    subject_label: string;
};

/**
 * The Server-owned Agent Attention kinds (design §8.4.2). Node, Network, and
 * Settings kinds are never acknowledgeable.
 */
export type AttentionKind = 'agent_offline' | 'agent_spool_fatal' | 'agent_spool_overflow' | 'agent_report_gap' | 'agent_security_event' | 'agent_shutdown_incomplete' | 'agent_inventory_rejected' | 'node_unhealthy' | 'node_health_unknown' | 'node_resync' | 'node_identity_mismatch';

export type AttentionSeverity = 'critical' | 'warning';

export type AttentionSubjectKind = 'agent' | 'node' | 'network' | 'settings';

/**
 * One immutable, redacted Audit row. `details` is the stored `after_json`
 * body, which is redacted by construction (ids, instants, and counts only
 * — never passwords, tokens, credentials, endpoints, raw peer IPs, or
 * complete request bodies).
 */
export type AuditItem = {
    actorUsername?: string | null;
    auditEventId: number;
    createdAt: string;
    details?: unknown;
    eventKind: string;
    targetId: string;
    targetKind: string;
};

export type AuditResponse = {
    items: Array<AuditItem>;
    /**
     * Cursor for the next older page; absent when the listing is complete.
     */
    nextBefore?: number | null;
};

export type BackupArtifactDetail = {
    artifact: BackupArtifactSummary;
    verificationError?: string | null;
};

export type BackupArtifactSummary = {
    artifactId: string;
    bytes: number;
    createOperationId?: string | null;
    createdAt: string;
    dataRangeMax?: string | null;
    dataRangeMin?: string | null;
    filename: string;
    schemaVersion: number;
    serverVersion: string;
    sha256: string;
    verification: string;
    verifiedAt?: string | null;
    /**
     * The most recent Operation that verified this artifact, so the page can
     * link the recorded outcome to the task that produced it. Absent means no
     * verification task ever recorded a result for this artifact.
     */
    verifyOperationId?: string | null;
};

/**
 * One protection interval: why it opened, what was skipped, and, once the
 * filesystem recovered, the measurement that closed it.
 */
export type CapacityIntervalDto = {
    /**
     * Null while protection is still active.
     */
    endedAt?: string | null;
    /**
     * "resumed" or "protection_disabled", null while active.
     */
    endedReason?: string | null;
    intervalId: string;
    openedAvailableBytes: number;
    openedTotalBytes: number;
    pauseBelowBytes: number;
    resumeAboveBytes: number;
    resumedAvailableBytes?: number | null;
    resumedTotalBytes?: number | null;
    /**
     * Optional readings counted as skipped during this interval, every series
     * together. Recorded synchronization and consensus states are optional
     * readings too, so they are counted here beside the metric samples.
     */
    skippedSampleCount: number;
    /**
     * The series that skipped the most readings, bounded.
     */
    skippedSeries: Array<CapacitySkippedSeriesDto>;
    /**
     * How many series counted at least one skipped reading.
     */
    skippedSeriesTotal: number;
    sourceMount: string;
    startedAt: string;
    startedReason: string;
    updatedAt: string;
};

/**
 * Capacity visibility and low-space protection state for Operations.
 */
export type CapacityOverview = {
    activeIntervalId?: string | null;
    enabled: boolean;
    /**
     * The directory that is measured, null when it cannot be resolved.
     */
    mountPath?: string | null;
    /**
     * Null when the policy is disabled, because nothing is invented in its place.
     */
    pauseBelowBytes?: number | null;
    /**
     * The configuration file the policy was read from.
     */
    policyOrigin?: string | null;
    protected: boolean;
    recentIntervals: Array<CapacityIntervalDto>;
    resumeAboveBytes?: number | null;
    sample?: null | CapacitySampleDto;
    sampleIntervalSeconds: number;
    /**
     * When the newest successful measurement was taken.
     */
    sampledAt?: string | null;
    /**
     * Set when the most recent sampling attempt failed, while the last good
     * measurement above is retained.
     */
    samplingError?: string | null;
    /**
     * Set when a protection transition could not be recorded durably.
     */
    transitionError?: string | null;
};

/**
 * One measurement of the filesystem that holds the Server state.
 */
export type CapacitySampleDto = {
    /**
     * The bytes still available to the Server user.
     */
    availableBytes: number;
    /**
     * The directory that was measured.
     */
    mountPath: string;
    /**
     * The filesystem size in bytes.
     */
    totalBytes: number;
};

/**
 * One series whose optional history lost readings while protection was active.
 */
export type CapacitySkippedSeriesDto = {
    /**
     * The series' dimension: the mount path of a Host storage series, empty for
     * every series an owner and metric identify on their own. Two mounts of one
     * Host are two series, so their losses are counted apart rather than merged.
     */
    dimension: string;
    /**
     * The first skipped observation, in RFC 3339.
     */
    firstSkippedAt: string;
    /**
     * The most recent skipped observation, in RFC 3339.
     */
    lastSkippedAt: string;
    /**
     * The optional metric that was skipped.
     */
    metric: string;
    /**
     * The node or agent identity the series belongs to.
     */
    scopeKey: string;
    /**
     * Either "node" or "host".
     */
    scopeKind: string;
    /**
     * How many readings this series counted as skipped. Counting follows the
     * recorded high-water mark, so an accepted Report retry that re-sends the
     * newest reading is never a second lost sample and the number never
     * claims more losses than the series accounted for.
     */
    skippedCount: number;
};

